<header>
  <h1><span>◆</span> Service Registration</h1>
</header>
<main>
  <div class="panel" id="panel">
    <h2>Create your account</h2>
    <p class="subtitle">Fill in the details below to register.</p>
    <form id="regForm" novalidate>
      <div class="grid">
        <div class="field">
          <label for="username">Username</label>
          <input type="text" id="username" name="username" autocomplete="username" required minlength="3" maxlength="30" pattern="[A-Za-z0-9_-]+" aria-describedby="username-hint">
          <div class="hint" id="username-hint">3–30 characters: letters, numbers, _ or -</div>
        </div>
        <div class="field">
          <label for="email">Email address</label>
          <input type="email" id="email" name="email" autocomplete="email" required aria-describedby="email-hint">
          <div class="hint" id="email-hint">We'll never share your email.</div>
        </div>
        <div class="field">
          <label for="dob">Date of birth <span class="opt">(optional)</span></label>
          <input type="date" id="dob" name="dob" autocomplete="bday" aria-describedby="dob-hint">
          <div class="hint" id="dob-hint"></div>
        </div>
        <div class="field"></div>
        <div class="field">
          <label for="password">Password</label>
          <div class="pw-wrap">
            <input type="password" id="password" name="password" autocomplete="new-password" required minlength="8" aria-describedby="pw-hint">
            <button type="button" class="pw-toggle" aria-label="Show password" data-target="password">Show</button>
          </div>
          <div class="hint" id="pw-hint">At least 8 characters with uppercase, lowercase, and a digit or symbol.</div>
        </div>
        <div class="field">
          <label for="confirm">Confirm password</label>
          <div class="pw-wrap">
            <input type="password" id="confirm" name="confirm" autocomplete="new-password" required aria-describedby="confirm-hint">
            <button type="button" class="pw-toggle" aria-label="Show password confirmation" data-target="confirm">Show</button>
          </div>
          <div class="hint" id="confirm-hint"></div>
        </div>
      </div>
      <div class="terms">
        <input type="checkbox" id="terms" name="terms" required>
        <label for="terms">I agree to the <a href="#" onclick="event.preventDefault()">Terms of Service</a> and <a href="#" onclick="event.preventDefault()">Privacy Policy</a>.</label>
      </div>
      <div class="hint error" id="terms-hint" style="margin-top:-.8rem;margin-bottom:1rem"></div>
