    if(!hasUpper||!hasLower||!hasOther){if(show)setHint(password,'pw-hint','Need uppercase, lowercase, and a digit or symbol.','error');password.classList.add('invalid');password.classList.remove('valid');return false}
    setHint(password,'pw-hint','✓ Strong password.','ok');
    password.classList.remove('invalid');password.classList.add('valid');
    return true;
  }

  function validateConfirm(show){
    const v=confirm.value;
    if(!v){if(show)setHint(confirm,'confirm-hint','Please confirm your password.','error');confirm.classList.add('invalid');confirm.classList.remove('valid');return false}
    if(v!==password.value){if(show)setHint(confirm,'confirm-hint','Passwords do not match.','error');confirm.classList.add('invalid');confirm.classList.remove('valid');return false}
    setHint(confirm,'confirm-hint','✓ Match.','ok');
    confirm.classList.remove('invalid');confirm.classList.add('valid');
    return true;
  }

  function validateDob(show){
    const v=dob.value;
    if(!v){setHint(dob,'dob-hint','','');dob.classList.remove('invalid','valid');return true}
    const d=new Date(v);
    const now=new Date();
    if(isNaN(d.getTime())){if(show)setHint(dob,'dob-hint','Please enter a valid date.','error');dob.classList.add('invalid');dob.classList.remove('valid');return false}
    if(d>now){if(show)setHint(dob,'dob-hint','Date cannot be in the future.','error');dob.classList.add('invalid');dob.classList.remove('valid');return false}
