    if(age<13){if(show)setHint(dob,'dob-hint','You must be at least 13 to register.','error');dob.classList.add('invalid');dob.classList.remove('valid');return false}
    setHint(dob,'dob-hint','✓','ok');
    dob.classList.remove('invalid');dob.classList.add('valid');
    return true;
  }

  function validateTerms(){
    if(!terms.checked){document.getElementById('terms-hint').textContent='You must accept the terms.';return false}
    document.getElementById('terms-hint').textContent='';return true;
  }

  form.addEventListener('submit',function(e){
    e.preventDefault();
    const results=[validateUsername(true),validateEmail(true),validateDob(true),validatePassword(true),validateConfirm(true),validateTerms()];
    if(results.every(Boolean)){
      const reg=getRegistry();
      reg.push({username:username.value.trim().toLowerCase(),email:email.value.trim().toLowerCase()});
      saveRegistry(reg);
      form.hidden=true;
      success.hidden=false;
      success.setAttribute('tabindex','-1');
      success.focus();
    }
  });
})();
